321 /// preserved.
322 static void ClearSubclassDataAfterReassociation(BinaryOperator &I) {
323   FPMathOperator *FPMO = dyn_cast<FPMathOperator>(&I);
324   if (!FPMO) {
325     I.clearSubclassOptionalData();
